SELECT
    person_name AS name,
    SUM(person_count) AS value
FROM stat_pp_person_type_cache


        AND company_code IN
        #{c}


        AND county_code = #{countyCode}


        AND park_code = #{parkCode}


        AND yq_type = #{yqType}


        AND is_scqy = #{isScqy}


GROUP BY person_name
ORDER BY value DESC
